mapper.select:
SELECT BOARD_ID, BOARD_TYPE, TITLE, CONTENT, REGISTER, REGIST_DT FROM BOARD WHERE BOARD_TYPE IN ('CK', 'TOAST', 'FAQ', 'QNA') AND ( TITLE LIKE '%' || #{searchKeyword} || '%'
OR SEARCH_CHOSUNG LIKE '%' || #{searchChosung} || '%'
) ORDER BY REGIST_DT DESC, BOARD_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.update:
UPDATE BOARD
SET SEARCH_CHOSUNG = #{searchChosung}
WHERE BOARD_ID = #{boardId}

mapper.select:
SELECT COUNT(*) FROM BOARD WHERE BOARD_TYPE IN ('CK', 'TOAST', 'FAQ', 'QNA') AND ( TITLE LIKE '%' || #{searchKeyword} || '%'
OR SEARCH_CHOSUNG LIKE '%' || #{searchChosung} || '%'
)
